// Navbar.js
import React from "react";
import styled, { keyframes } from "styled-components";

// --- floating animation ---
const floatIn = keyframes`
  0% { opacity: 0; transform: translateY(-30px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
`;

const NavContainer = styled.div`
  position: fixed;
  top: 60px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(11, 15, 20, 0.92);
  padding: 16px 36px;
  border-radius: 60px;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
  display: flex;
  align-items: center;
  justify-content: center; /* Center the inner content */
  min-width: 450px;
  max-width: 90%;
  z-index: 999;
  backdrop-filter: blur(14px);
  animation: ${floatIn} 0.6s ease forwards;
`;

const NavContent = styled.div`
  display: flex;
  align-items: center;
  gap: 24px; /* space between title and buttons */
`;

const Title = styled.div`
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #e6eef8;
`;

const NavButtons = styled.div`
  display: flex;
  gap: 12px;

  button {
    padding: 8px 18px;
    border-radius: 30px;
    border: none;
    background: rgba(255,255,255,0.06);
    color: #e6eef8;
    font-weight: 500;
    font-size: 14px;
    transition: all 0.25s ease;
    cursor: pointer;
    backdrop-filter: blur(10px);

    &:hover {
      background: rgba(97, 218, 251, 0.25);
      color: #61dafb;
      transform: scale(1.07);
      box-shadow: 0 4px 20px rgba(97,218,251,0.3);
    }

    &:active {
      transform: scale(0.97);
    }
  }
`;

export default function Navbar() {
  return (
    <NavContainer>
      <NavContent>
        <Title>Dashboard</Title>
        <NavButtons>
          <button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}>
            Home
          </button>
          <button onClick={() => window.open("https://instagram.com/_zainn.27", "_blank")}>
            Instagram
          </button>
        </NavButtons>
      </NavContent>
    </NavContainer>
  );
}
